LESSON_JSON = "{\n \"id\": \"nonparamt7\",\n \"topicId\": \"nonparam-t7\",\n \"moduleId\": \"nonparam\",\n \"title\": \"Empirical distribution function and properties\",\n \"breadcrumb\": \"Non-parametric methods → Empirical distribution function → Definition and properties\",\n \"engine\": \"B\",\n \"engineName\": \"Count observations at or below x, then divide by n.\",\n \"version\": \"1.0\",\n \"status\": \"approved\",\n \"estMin\": 96,\n \"objectives\": [\n  \"Construct the empirical distribution function from a sample.\",\n  \"Describe monotonicity, right-continuity, limits and jump sizes, including ties.\",\n  \"Derive the pointwise expectation and variance of the empirical CDF.\",\n  \"Calculate empirical quantiles using the inverse-CDF convention.\",\n  \"State the Glivenko–Cantelli theorem and connect the EDF to KS testing.\"\n ],\n \"prereq\": [\n  {\n   \"id\": \"p1\",\n   \"name\": \"Cumulative distribution function\",\n   \"why\": \"The empirical CDF estimates the population CDF at each threshold.\"\n  },\n  {\n   \"id\": \"p2\",\n   \"name\": \"Indicator variables\",\n   \"why\": \"The empirical CDF is an average of indicator variables.\"\n  },\n  {\n   \"id\": \"p3\",\n   \"name\": \"Order statistics and quantiles\",\n   \"why\": \"Empirical quantiles are selected from the ordered sample.\"\n  }\n ],\n \"traps\": [\n  \"The definition uses Xᵢ≤x, not Xᵢ<x.\",\n  \"A tie of size m creates a jump m/n, not 1/n.\",\n  \"Fₙ is nondecreasing and right-continuous; it never decreases.\",\n  \"E[Fₙ(x)]=F(x), while Var[Fₙ(x)]=F(x){1−F(x)}/n.\",\n  \"Uniform convergence is stronger than pointwise convergence.\",\n  \"The inverse-CDF median convention for even n may differ from averaging the two middle values.\"\n ],\n \"howto\": \"Sort the sample, count observations at or below each threshold, and divide by n. At a tie, include the full tied group in the jump. Use the expectation and variance formulas for pointwise inference; use the inverse-CDF convention explicitly when finding quantiles.\",\n \"revision\": {\n  \"sheet\": [\n   \"Fₙ(x)=1/n ΣI(Xᵢ≤x).\",\n   \"Fₙ is nondecreasing, right-continuous, zero below the sample minimum and one at/above the maximum.\",\n   \"Jump at x with multiplicity mₓ: mₓ/n.\",\n   \"E[Fₙ(x)]=F(x) for iid observations.\",\n   \"Var[Fₙ(x)]=F(x){1−F(x)}/n.\",\n   \"For x≤y, Cov(Fₙ(x),Fₙ(y))=[F(x)−F(x)F(y)]/n.\",\n   \"Empirical inverse-CDF quantile: Fₙ⁻¹(p)=X_(ceil(np)), 0<p≤1.\",\n   \"Glivenko–Cantelli: supₓ|Fₙ(x)−F(x)|→0 almost surely.\",\n   \"KS uses supₓ|Fₙ(x)−F₀(x)|.\",\n   \"For even n, inverse-CDF median may be lower central order statistic; some sample median conventions average the middle pair.\"\n  ],\n  \"cards\": [\n   [\n    \"Definition\",\n    \"Fₙ(x)=count(Xᵢ≤x)/n\"\n   ],\n   [\n    \"Jump size\",\n    \"mₓ/n\"\n   ],\n   [\n    \"Expectation\",\n    \"F(x)\"\n   ],\n   [\n    \"Variance\",\n    \"F(x){1−F(x)}/n\"\n   ],\n   [\n    \"Quantile index\",\n    \"ceil(np)\"\n   ],\n   [\n    \"Glivenko–Cantelli\",\n    \"Uniform convergence almost surely\"\n   ],\n   [\n    \"KS link\",\n    \"sup|Fₙ−F₀|\"\n   ],\n   [\n    \"Even-n median\",\n    \"State the convention\"\n   ]\n  ],\n  \"tricks\": [\n   \"Use ≤x: equal observations count.\",\n   \"Check all jumps sum to one.\",\n   \"Variance is largest at F(x)=0.5 and equals 1/(4n).\"\n  ],\n  \"shortcuts\": [\n   \"Tie jump = multiplicity/n.\",\n   \"Pointwise variance = F(1−F)/n.\",\n   \"Empirical p-quantile index = ceil(np).\"\n  ],\n  \"remember\": [\n   \"EDF is a complete sample distribution summary.\",\n   \"Uniform convergence controls the largest gap over all x.\"\n  ]\n },\n \"refs\": [\n  {\n   \"title\": \"Nonparametric Statistical Methods\",\n   \"where\": \"Empirical distribution and goodness-of-fit\",\n   \"site\": \"Hollander, Wolfe and Chicken\",\n   \"url\": \"\",\n   \"type\": \"Textbook\",\n   \"free\": false,\n   \"checked\": \"2026-11-12\",\n   \"why\": \"Standard treatment of empirical distribution functions.\"\n  },\n  {\n   \"title\": \"NIST/SEMATECH e-Handbook of Statistical Methods\",\n   \"where\": \"Empirical distribution and goodness-of-fit\",\n   \"site\": \"NIST\",\n   \"url\": \"https://www.itl.nist.gov/div898/handbook/\",\n   \"type\": \"Free online textbook\",\n   \"free\": true,\n   \"checked\": \"2026-11-12\",\n   \"why\": \"Applied reference for EDF and goodness-of-fit.\"\n  },\n  {\n   \"title\": \"Penn State STAT 415\",\n   \"where\": \"Nonparametric methods\",\n   \"site\": \"Penn State\",\n   \"url\": \"https://online.stat.psu.edu/stat415/\",\n   \"type\": \"Free online textbook\",\n   \"free\": true,\n   \"checked\": \"2026-11-12\",\n   \"why\": \"Accessible supporting material for distribution functions.\"\n  }\n ],\n \"mastery\": {\n  \"minQ\": 10,\n  \"pass\": 80,\n  \"draw\": 10,\n  \"fmtMin\": {\n   \"numeric\": 70,\n   \"multi\": 70\n  },\n  \"diffMix\": {\n   \"easy\": 3,\n   \"moderate\": 5,\n   \"hard\": 2\n  },\n  \"noHints\": true,\n  \"retestDays\": 7,\n  \"note\": \"Proposed platform settings, not an NTA rule. Overall 80%, with 70% floors on numerical and multi-statement items, answered without hints.\"\n },\n \"provenance\": \"The empirical distribution function topic is included in the 2026 syllabus audit. The inspected June 2026 nonparametric Q33/Q42 variants do not contain a direct EDF-theorem stem; the lesson therefore teaches the syllabus definition, jump properties, unbiasedness, variance, inverse-CDF quantiles and Glivenko–Cantelli result. Constructed numeric examples are independently recomputed in the verification script.\",\n \"scenes\": [\n  {\n   \"kind\": \"foundation\",\n   \"id\": \"s0\",\n   \"mins\": 7,\n   \"title\": \"Start with cumulative probability\",\n   \"objective\": \"Connect a CDF, a sample proportion and an indicator.\",\n   \"ask\": {\n    \"q\": \"What does F(x)=P(X≤x) measure?\",\n    \"nudge\": \"The probability accumulated up to and including x.\"\n   },\n   \"body\": [\n    \"A cumulative distribution function records the probability that a random variable is at most a chosen threshold. It accumulates probability from left to right.\",\n    \"The empirical distribution function replaces the population probability with the fraction of sample observations at or below the threshold.\"\n   ],\n   \"items\": [\n    {\n     \"ask\": \"What does the indicator I(Xᵢ≤x) equal?\",\n     \"recall\": \"One if Xᵢ≤x, and zero otherwise.\",\n     \"refresh\": [\n      \"An indicator records whether a condition is true. It equals one when the observation is at most x and zero otherwise.\",\n      \"Adding these indicators counts the sample observations that are at most x. Dividing by n converts the count to a proportion.\"\n     ]\n    },\n    {\n     \"ask\": \"What is a sample proportion?\",\n     \"recall\": \"A count divided by the sample size.\",\n     \"refresh\": [\n      \"If 6 of 10 observations satisfy a condition, the sample proportion is 6/10=0.6.\",\n      \"An empirical CDF is a cumulative sample proportion: it counts all observations up to the current threshold, not only those equal to it.\"\n     ]\n    },\n    {\n     \"ask\": \"What does nondecreasing mean?\",\n     \"recall\": \"The function can stay constant or increase, but cannot fall as x increases.\",\n     \"refresh\": [\n      \"As the threshold increases, every observation already counted remains counted. New observations may be added, but none are removed.\",\n      \"Therefore a CDF is nondecreasing. The same property holds for the empirical CDF.\"\n     ]\n    }\n   ]\n  },\n  {\n   \"kind\": \"intuition\",\n   \"id\": \"s1\",\n   \"mins\": 7,\n   \"title\": \"A staircase that records the sample\",\n   \"objective\": \"Understand why the empirical CDF is a step function.\",\n   \"ask\": {\n    \"q\": \"What happens at a distinct observed value?\",\n    \"nudge\": \"The empirical CDF jumps upward by 1/n.\"\n   },\n   \"body\": [\n    \"Sort the observations. Before the smallest value the empirical CDF is zero. At each distinct observed value it jumps by the number of observations tied there divided by n.\",\n    \"Between observed values the function is flat. After the largest value it equals one. This staircase records the complete empirical distribution.\"\n   ],\n   \"scenario\": {\n    \"teaser\": \"A sample of customer waiting times.\",\n    \"title\": \"Estimating the five-minute proportion\",\n    \"body\": [\n     \"A survey records the waiting times of 10 customers. The empirical distribution function at five minutes is the proportion of the observed waiting times that are no greater than five minutes. As the time threshold moves from left to right, this cumulative proportion can stay flat or jump upward; it never decreases. If three customers have exactly the same waiting time, the empirical CDF makes one jump of size 3/10 at that value. This step curve gives a complete summary of the observed distribution and is the basis of the one-sample KS statistic.\"\n    ],\n    \"q\": \"If three of the 10 customers have exactly the same waiting time, how large is the jump at that value?\",\n    \"answer\": \"The jump is 3/10=0.3.\"\n   }\n  },\n  {\n   \"kind\": \"explore\",\n   \"id\": \"s2\",\n   \"mins\": 6,\n   \"title\": \"Construct the empirical CDF\",\n   \"objective\": \"Translate observations into cumulative proportions.\",\n   \"ask\": {\n    \"q\": \"For sample values 2, 3, 3, 4, 6, what is Fₙ(3)?\",\n    \"nudge\": \"Three of the five observations are at most 3.\"\n   },\n   \"viz\": {\n    \"type\": \"rank-null\",\n    \"caption\": \"The empirical CDF rises by the relative frequency at each observed value and remains flat between values.\"\n   },\n   \"body\": [\n    \"For observations 2, 3, 3, 4, 6, the empirical CDF at x=3 is 3/5=0.6. It includes both observations equal to 3 and the observation equal to 2.\",\n    \"The jump at x=3 is 2/5 because two observations are tied there. Just before x=3, Fₙ is 1/5; at x=3, it becomes 3/5.\"\n   ]\n  },\n  {\n   \"kind\": \"theory\",\n   \"id\": \"s3\",\n   \"mins\": 9,\n   \"title\": \"Definition and sample properties\",\n   \"objective\": \"State the empirical CDF formula and its main properties.\",\n   \"ask\": {\n    \"q\": \"What is the jump size at a value observed m times?\",\n    \"nudge\": \"m/n.\"\n   },\n   \"blocks\": [\n    {\n     \"t\": \"formula\",\n     \"h\": \"Definition\",\n     \"body\": \"Fₙ(x)=1/n Σᵢ₌₁ⁿ I(Xᵢ≤x). It is the sample proportion of observations no greater than x.\"\n    },\n    {\n     \"t\": \"def\",\n     \"h\": \"Shape\",\n     \"body\": \"Fₙ is nondecreasing, right-continuous, equals zero below the sample minimum and equals one at or above the sample maximum.\"\n    },\n    {\n     \"t\": \"formula\",\n     \"h\": \"Jump size\",\n     \"body\": \"At a value x occurring mₓ times, Fₙ(x)−Fₙ(x⁻)=mₓ/n. With no ties, each jump is 1/n.\"\n    },\n    {\n     \"t\": \"formula\",\n     \"h\": \"Pointwise moments\",\n     \"body\": \"For an iid sample, E[Fₙ(x)]=F(x) and Var[Fₙ(x)]=F(x){1−F(x)}/n.\"\n    },\n    {\n     \"t\": \"step\",\n     \"h\": \"Uniform convergence\",\n     \"body\": \"The Glivenko–Cantelli theorem states supₓ|Fₙ(x)−F(x)|→0 almost surely as n→∞. The empirical CDF converges uniformly to the population CDF.\"\n    }\n   ],\n   \"flow\": {\n    \"title\": \"Build the empirical CDF\",\n    \"alt\": \"Choose a threshold, count observations at or below it, divide by n, and repeat across thresholds to obtain a nondecreasing step function.\",\n    \"nodes\": [\n     {\n      \"id\": \"a\",\n      \"r\": 0,\n      \"c\": 1,\n      \"label\": \"Choose threshold x\",\n      \"kind\": \"start\"\n     },\n     {\n      \"id\": \"b\",\n      \"r\": 1,\n      \"c\": 1,\n      \"label\": \"Count Xᵢ≤x\",\n      \"kind\": \"step\"\n     },\n     {\n      \"id\": \"c\",\n      \"r\": 2,\n      \"c\": 1,\n      \"label\": \"Divide by n\",\n      \"kind\": \"step\"\n     },\n     {\n      \"id\": \"d\",\n      \"r\": 3,\n      \"c\": 1,\n      \"label\": \"Plot cumulative proportion\",\n      \"kind\": \"step\"\n     },\n     {\n      \"id\": \"e\",\n      \"r\": 4,\n      \"c\": 1,\n      \"label\": \"Repeat across x\",\n      \"kind\": \"end\"\n     }\n    ],\n    \"edges\": [\n     {\n      \"from\": \"a\",\n      \"to\": \"b\"\n     },\n     {\n      \"from\": \"b\",\n      \"to\": \"c\"\n     },\n     {\n      \"from\": \"c\",\n      \"to\": \"d\"\n     },\n     {\n      \"from\": \"d\",\n      \"to\": \"e\"\n     }\n    ],\n    \"note\": \"At tied values the jump equals tie frequency divided by sample size.\"\n   }\n  },\n  {\n   \"kind\": \"worked\",\n   \"id\": \"s4\",\n   \"mins\": 10,\n   \"title\": \"Worked example: tied observations\",\n   \"objective\": \"Calculate the CDF value and jump at a tie.\",\n   \"ask\": {\n    \"q\": \"Why is Fₙ(3) equal to 3/5 rather than 2/5?\",\n    \"nudge\": \"It includes all observations less than or equal to 3.\"\n   },\n   \"problem\": \"The sample is 2, 3, 3, 4, 6. Find Fₙ(3), Fₙ(3⁻) and the jump at 3.\",\n   \"steps\": [\n    {\n     \"say\": \"Count observations at most 3.\",\n     \"math\": \"2, 3, 3 → count=3\",\n     \"why\": \"The definition uses Xᵢ≤x, including values equal to x.\"\n    },\n    {\n     \"say\": \"Divide by n=5.\",\n     \"math\": \"Fₙ(3)=3/5=0.6\",\n     \"why\": \"The empirical CDF is a cumulative proportion.\"\n    },\n    {\n     \"say\": \"Count observations strictly below 3.\",\n     \"math\": \"Only 2 → Fₙ(3⁻)=1/5=0.2\",\n     \"why\": \"The left limit excludes values equal to 3.\"\n    },\n    {\n     \"say\": \"Subtract to obtain the jump.\",\n     \"math\": \"0.6−0.2=0.4=2/5\",\n     \"why\": \"There are two observations tied at 3, so the jump is tie frequency divided by n.\"\n    }\n   ],\n   \"after\": \"The value of the CDF at x includes observations equal to x; the left limit does not.\"\n  },\n  {\n   \"kind\": \"recall\",\n   \"id\": \"s5\",\n   \"mins\": 3,\n   \"title\": \"Pause and retrieve\",\n   \"objective\": \"Recall the definition and shape.\",\n   \"intro\": \"Answer before revealing.\",\n   \"items\": [\n    {\n     \"q\": \"Formula for Fₙ(x)?\",\n     \"a\": \"(1/n)ΣI(Xᵢ≤x).\"\n    },\n    {\n     \"q\": \"Jump size for m ties in a sample of size n?\",\n     \"a\": \"m/n.\"\n    },\n    {\n     \"q\": \"Can an empirical CDF decrease?\",\n     \"a\": \"No; it is nondecreasing.\"\n    },\n    {\n     \"q\": \"What is Fₙ(x) above the sample maximum?\",\n     \"a\": \"One.\"\n    },\n    {\n     \"q\": \"What does the Glivenko–Cantelli theorem state?\",\n     \"a\": \"Uniform convergence of Fₙ to F almost surely.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"completion\",\n   \"id\": \"s6\",\n   \"mins\": 8,\n   \"title\": \"Complete the CDF calculation\",\n   \"objective\": \"Fill the cumulative count and jump.\",\n   \"problem\": \"A sample of size 8 has five observations at or below x, of which two equal x. Find Fₙ(x), Fₙ(x⁻) and the jump.\",\n   \"steps\": [\n    {\n     \"say\": \"Calculate the empirical CDF.\",\n     \"blank\": {\n      \"prompt\": \"Fₙ(x)=5/8=…\",\n      \"answer\": \"0.625\",\n      \"accept\": [\n       \"0.625\"\n      ],\n      \"hint\": \"Divide five by eight.\"\n     },\n     \"why\": \"Five of eight observations are at most x.\"\n    },\n    {\n     \"say\": \"Find the left limit.\",\n     \"blank\": {\n      \"prompt\": \"Fₙ(x⁻)=(5−2)/8=…\",\n      \"answer\": \"0.375\",\n      \"accept\": [\n       \"0.375\"\n      ],\n      \"hint\": \"Remove the two observations equal to x before dividing.\"\n     },\n     \"why\": \"The left limit counts only observations strictly below x.\"\n    },\n    {\n     \"say\": \"Find the jump.\",\n     \"blank\": {\n      \"prompt\": \"Fₙ(x)−Fₙ(x⁻)=2/8=…\",\n      \"answer\": \"0.25\",\n      \"accept\": [\n       \"0.250\"\n      ],\n      \"hint\": \"The jump equals the tie frequency divided by n.\"\n     },\n     \"why\": \"Two observations are tied at x, so the jump is 2/8.\"\n    }\n   ],\n   \"after\": \"Check that the jump is exactly the relative frequency of the tied observations.\",\n   \"ask\": {\n    \"q\": \"Which observations enter the numerator of Fₙ(x)?\",\n    \"nudge\": \"All observations less than or equal to x, including ties at x.\"\n   }\n  },\n  {\n   \"kind\": \"theory\",\n   \"id\": \"s7\",\n   \"mins\": 8,\n   \"title\": \"Sampling properties and quantiles\",\n   \"objective\": \"Use the empirical CDF to estimate probabilities and quantiles.\",\n   \"ask\": {\n    \"q\": \"If F(x)=0.4 and n=10, what is Var[Fₙ(x)]?\",\n    \"nudge\": \"Use F(x){1−F(x)}/n.\"\n   },\n   \"blocks\": [\n    {\n     \"t\": \"formula\",\n     \"h\": \"Unbiasedness\",\n     \"body\": \"For iid observations, E[Fₙ(x)]=F(x). At a fixed x, the empirical CDF is an unbiased estimator of the population CDF.\"\n    },\n    {\n     \"t\": \"formula\",\n     \"h\": \"Variance\",\n     \"body\": \"Var[Fₙ(x)]=F(x){1−F(x)}/n. The variance decreases as n increases.\"\n    },\n    {\n     \"t\": \"def\",\n     \"h\": \"Empirical quantile\",\n     \"body\": \"For 0<p≤1, define Fₙ⁻¹(p)=inf{x:Fₙ(x)≥p}. With ordered observations this is X_(ceil(np)) under the inverse-CDF convention.\"\n    },\n    {\n     \"t\": \"step\",\n     \"h\": \"Median caution\",\n     \"body\": \"The inverse-CDF empirical median for even n selects the lower central order statistic. Some sample-median conventions average the two middle observations; state the convention used.\"\n    },\n    {\n     \"t\": \"def\",\n     \"h\": \"Link to KS\",\n     \"body\": \"The one-sample KS statistic is supₓ|Fₙ(x)−F₀(x)|. The empirical CDF is therefore the central object in goodness-of-fit comparisons.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"guided\",\n   \"id\": \"s8\",\n   \"mins\": 8,\n   \"title\": \"Guided calculation: pointwise variance\",\n   \"objective\": \"Calculate the sampling variance of Fₙ(x).\",\n   \"problem\": \"At a fixed x, the population CDF is F(x)=0.4 and the sample size is n=10. Find E[Fₙ(x)] and Var[Fₙ(x)].\",\n   \"hints\": [\n    \"Use unbiasedness for the expectation.\",\n    \"Substitute F(x) and n into F(1−F)/n.\",\n    \"Check that a proportion variance is nonnegative and no larger than 1/(4n).\"\n   ],\n   \"answer\": \"E[Fₙ(x)]=0.4 and Var[Fₙ(x)]=0.4×0.6/10=0.024.\",\n   \"check\": \"The maximum pointwise variance is 1/(4n)=0.025, so 0.024 is plausible.\",\n   \"solution\": [\n    {\n     \"say\": \"Use the expectation property.\",\n     \"math\": \"E[Fₙ(x)]=F(x)=0.4\",\n     \"why\": \"The empirical CDF is unbiased at each fixed x.\"\n    },\n    {\n     \"say\": \"Substitute into the variance.\",\n     \"math\": \"Var[Fₙ(x)]=0.4(1−0.4)/10\",\n     \"why\": \"Use the Bernoulli-proportion variance divided by n.\"\n    },\n    {\n     \"say\": \"Evaluate.\",\n     \"math\": \"0.4×0.6/10=0.24/10=0.024\",\n     \"why\": \"The variance is nonnegative and below the maximum 1/(4n)=0.025.\"\n    }\n   ],\n   \"scenario\": {\n    \"teaser\": \"A sample estimates the proportion of households below a travel-time threshold.\",\n    \"title\": \"Estimating a population proportion\",\n    \"body\": [\n     \"A public-health analyst uses the empirical CDF to estimate the proportion of households whose travel time is at most 30 minutes. With a random sample, the empirical proportion is unbiased for the corresponding population probability, and its variance is F(x){1−F(x)}/n. Increasing the sample size reduces this pointwise variance. The empirical CDF also converges uniformly to the true CDF with probability one, a result known as the Glivenko–Cantelli theorem.\"\n    ],\n    \"q\": \"Why does increasing n improve pointwise precision of the empirical CDF?\",\n    \"answer\": \"Its variance is F(x){1−F(x)}/n, which decreases as n increases.\"\n   },\n   \"ask\": {\n    \"q\": \"Which formula gives the pointwise variance of Fₙ(x)?\",\n    \"nudge\": \"F(x){1−F(x)}/n.\"\n   }\n  },\n  {\n   \"kind\": \"trapcheck\",\n   \"id\": \"s9\",\n   \"mins\": 6,\n   \"title\": \"Six statements to challenge\",\n   \"objective\": \"Check the empirical CDF properties.\",\n   \"intro\": \"Mark each claim true or false before revealing the reason.\",\n   \"items\": [\n    {\n     \"claim\": \"Fₙ(x) counts observations strictly less than x.\",\n     \"tf\": false,\n     \"why\": \"False. The definition uses Xᵢ≤x, so observations equal to x are included.\"\n    },\n    {\n     \"claim\": \"Fₙ is nondecreasing.\",\n     \"tf\": true,\n     \"why\": \"True. Increasing x cannot remove observations already counted.\"\n    },\n    {\n     \"claim\": \"A tie of size m creates a jump of m/n.\",\n     \"tf\": true,\n     \"why\": \"True. The cumulative count increases by m at that value.\"\n    },\n    {\n     \"claim\": \"E[Fₙ(x)]=F(x) for an iid sample.\",\n     \"tf\": true,\n     \"why\": \"True. It is the average of n Bernoulli indicators with success probability F(x).\"\n    },\n    {\n     \"claim\": \"Var[Fₙ(x)] increases as n increases.\",\n     \"tf\": false,\n     \"why\": \"False. The variance is F(x){1−F(x)}/n, which decreases with sample size.\"\n    },\n    {\n     \"claim\": \"Glivenko–Cantelli gives uniform convergence almost surely.\",\n     \"tf\": true,\n     \"why\": \"True. The supremum distance between empirical and population CDFs tends to zero almost surely.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"guided\",\n   \"id\": \"s10\",\n   \"mins\": 8,\n   \"title\": \"Guided calculation: empirical quantile\",\n   \"objective\": \"Find an order statistic from the inverse-CDF definition.\",\n   \"problem\": \"A sample has n=12 ordered observations. Find the empirical 0.75-quantile using Fₙ⁻¹(p)=X_(ceil(np)).\",\n   \"hints\": [\n    \"Multiply p by n.\",\n    \"Take the ceiling of the result.\",\n    \"Select that order statistic from the sorted sample.\"\n   ],\n   \"answer\": \"ceil(0.75×12)=ceil(9)=9, so the empirical quantile is X_(9).\",\n   \"check\": \"The empirical CDF reaches at least 0.75 at the ninth ordered observation.\",\n   \"solution\": [\n    {\n     \"say\": \"Calculate np.\",\n     \"math\": \"np=0.75×12=9\",\n     \"why\": \"The inverse-CDF convention uses the ceiling of np.\"\n    },\n    {\n     \"say\": \"Take the ceiling.\",\n     \"math\": \"ceil(9)=9\",\n     \"why\": \"The index is an integer order-statistic position.\"\n    },\n    {\n     \"say\": \"Identify the quantile.\",\n     \"math\": \"Fₙ⁻¹(0.75)=X_(9)\",\n     \"why\": \"The ninth ordered observation is the first at which the empirical CDF reaches 0.75.\"\n    }\n   ],\n   \"ask\": {\n    \"q\": \"How do you find the inverse-CDF empirical p-quantile index?\",\n    \"nudge\": \"Take ceil(np).\"\n   }\n  },\n  {\n   \"kind\": \"theory\",\n   \"id\": \"s11\",\n   \"mins\": 6,\n   \"title\": \"Assumptions and interpretation\",\n   \"objective\": \"Know what the empirical CDF can and cannot claim.\",\n   \"ask\": {\n    \"q\": \"Does uniform convergence mean Fₙ(x)=F(x) for every finite sample?\",\n    \"nudge\": \"No; it means the maximum gap tends to zero as n grows.\"\n   },\n   \"blocks\": [\n    {\n     \"t\": \"def\",\n     \"h\": \"Sampling framework\",\n     \"body\": \"The standard unbiasedness, variance and Glivenko–Cantelli statements are presented for an iid sample from a population distribution F.\"\n    },\n    {\n     \"t\": \"step\",\n     \"h\": \"Pointwise vs uniform\",\n     \"body\": \"Pointwise convergence concerns one fixed x. Uniform convergence controls the largest absolute gap over all x simultaneously.\"\n    },\n    {\n     \"t\": \"def\",\n     \"h\": \"Interpretation\",\n     \"body\": \"Fₙ is a complete nonparametric summary of the observed univariate sample. It does not by itself establish causality or explain why the population distribution has its shape.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"recall\",\n   \"id\": \"s12\",\n   \"mins\": 3,\n   \"title\": \"Second recall\",\n   \"objective\": \"Retrieve the key properties and formulas.\",\n   \"intro\": \"Answer, then reveal.\",\n   \"items\": [\n    {\n     \"q\": \"E[Fₙ(x)]?\",\n     \"a\": \"F(x).\"\n    },\n    {\n     \"q\": \"Var[Fₙ(x)]?\",\n     \"a\": \"F(x){1−F(x)}/n.\"\n    },\n    {\n     \"q\": \"Jump at a tie of size m?\",\n     \"a\": \"m/n.\"\n    },\n    {\n     \"q\": \"Empirical p-quantile index?\",\n     \"a\": \"ceil(np), under the inverse-CDF convention.\"\n    },\n    {\n     \"q\": \"Glivenko–Cantelli convergence?\",\n     \"a\": \"supₓ|Fₙ(x)−F(x)|→0 almost surely.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"summary\",\n   \"id\": \"s13\",\n   \"mins\": 3,\n   \"title\": \"What you should now be able to do\",\n   \"objective\": \"Construct, analyse and interpret the empirical CDF.\",\n   \"body\": [\n    \"Calculate Fₙ(x) as the fraction of observations at most x, including ties at x.\",\n    \"Describe its step shape, right-continuity, monotonicity and jump sizes.\",\n    \"Use unbiasedness and the pointwise variance formula for probability estimation.\",\n    \"Find empirical quantiles using the inverse-CDF order-statistic convention.\",\n    \"State Glivenko–Cantelli uniform convergence and connect the EDF to KS goodness-of-fit.\"\n   ],\n   \"ask\": {\n    \"q\": \"What does Glivenko–Cantelli add beyond pointwise convergence?\",\n    \"nudge\": \"Uniform control of the maximum gap over all x.\"\n   }\n  },\n  {\n   \"kind\": \"quiz\",\n   \"id\": \"s14\",\n   \"mins\": 4,\n   \"title\": \"Mastery test\",\n   \"objective\": \"Demonstrate the empirical CDF skills independently.\",\n   \"setId\": \"nonparam_t7_mastery\"\n  }\n ]\n}"
